# Seçili siparişleri draft'a çevir
success_count = 0
error_count = 0
errors = []

for order in records:
    try:
        if order.state in ('purchase', 'done'):
            # Kilitli siparişi draft'a çevir
            order.button_draft()
            success_count += 1
        elif order.state == 'draft':
            # Zaten draft
            success_count += 1
        else:
            # Diğer durumlar (cancel, sent, to approve)
            errors.append(f"{order.name}: Durum '{order.state}' - draft'a çevrilemez")
            error_count += 1
    except Exception as e:
        errors.append(f"{order.name}: {str(e)}")
        error_count += 1

# Sonuç mesajı
if errors:
    error_msg = "\n".join(errors)
    raise UserError(f"Başarılı: {success_count}\nHatalı: {error_count}\n\nHatalar:\n{error_msg}")
else:
    raise UserError(f"Tamamlandı!\n\n{success_count} sipariş draft durumuna çevrildi.")

# Seçili siparişleri iptal et
success_count = 0
error_count = 0
errors = []

for order in records:
    try:
        if order.state == 'cancel':
            # Zaten iptal
            success_count += 1
        elif order.state in ('draft', 'sent', 'to approve', 'purchase', 'done'):
            # İptal edilebilir durumlar
            order.button_cancel()
            success_count += 1
        else:
            errors.append(f"{order.name}: Durum '{order.state}' - iptal edilemez")
            error_count += 1
    except Exception as e:
        errors.append(f"{order.name}: {str(e)}")
        error_count += 1

# Sonuç mesajı
if errors:
    error_msg = "\n".join(errors)
    raise UserError(f"Başarılı: {success_count}\nHatalı: {error_count}\n\nHatalar:\n{error_msg}")
else:
    raise UserError(f"Tamamlandı!\n\n{success_count} sipariş iptal edildi.")
